from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN, ROUND_HALF_UP
from typing import List, Union

from pydantic import BaseModel, conint, validator, ValidationError


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: Decimal

    @validator("unit_price", pre=True)
    def validate_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal, must be >= 0
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places exactly, rounding half up
        return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API with:
    - number (str)
    - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ in UTC
    - lines: list of {sku, quantity, unit_price} with unit_price as string with 2 decimals
    - total: string with 2 decimals (sum of quantity * unit_price)
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ (UTC)
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with exactly two decimals
    lines_out = []
    total = Decimal("0.00")
    for line in invoice.lines:
        line_total = line.unit_price * line.quantity
        total += line_total
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": f"{line.unit_price:.2f}",
            }
        )

    total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

    import json

    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }
    return json.dumps(out, separators=(",", ":"))

from typing import List, Optional

from pydantic import BaseModel, validator


class ImportProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def clean_display_name(cls, value: str) -> str:
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def zip_code_to_str(cls, value) -> str:
        # Accept int or str, store as str
        return str(value)


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = ImportProfile.parse_obj(row)
            # Return dict with only required keys in the requested order
            valid_profiles.append(
                {
                    "user_id": profile.user_id,
                    "display_name": profile.display_name,
                    "bio": profile.bio,
                    "zip_code": profile.zip_code,
                }
            )
        except Exception:
            # Silently skip invalid rows
            pass
    return valid_profiles

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import List, Union
from pydantic import BaseModel, field_validator, ValidationError
import json


class Line(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    model_config = {
        "from_attributes": True,
    }

    @field_validator("quantity")
    @classmethod
    def quantity_must_be_positive(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @field_validator("unit_price", mode="before")
    @classmethod
    def parse_unit_price(cls, v: Union[str, int, float, Decimal]) -> Decimal:
        try:
            d = Decimal(str(v))
        except (InvalidOperation, ValueError):
            raise ValueError("unit_price must be a decimal number")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimals for internal consistency (not strictly required here)
        return d.quantize(Decimal("0.01"))


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    model_config = {
        "from_attributes": True,
    }

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v: Union[str, datetime]) -> datetime:
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except ValueError:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt


