import re
from pydantic import BaseModel, field_validator, ValidationError


class SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @field_validator("username")
    @classmethod
    def username_valid(cls, v: str) -> str:
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @field_validator("email")
    @classmethod
    def email_valid(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @field_validator("phone")
    @classmethod
    def phone_valid(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        cleaned = re.sub(r"[ .\-\(\)]", "", v)
        if not re.fullmatch(r"\+[0-9]{8,15}", cleaned):
            raise ValueError("phone must be '+' followed by 8-15 digits after removing spaces/dots/dashes/parentheses")
        return cleaned

    @field_validator("password")
    @classmethod
    def password_length(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @field_validator("password_confirm")
    @classmethod
    def password_confirm_matches(cls, v: str, info) -> str:
        # We need to compare with password field
        password = info.data.get("password")
        if password is None:
            # password validation will raise separately if missing
            return v
        if v != password:
            raise ValueError("password_confirm must equal password")
        return v


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload and return dict with username, email, phone."""
    validated = SignupModel.model_validate(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }
